import time
import requests

RETRY_STATUS = {429, 500, 502, 503, 504}

def get_with_retry(url, retries=3, backoff=1.0, timeout=10, **kwargs):
    for attempt in range(retries + 1):
        try:
            response = requests.get(url, timeout=timeout, **kwargs)
            if response.status_code not in RETRY_STATUS:
                response.raise_for_status()
                return response
            error = requests.HTTPError(f"{response.status_code} for {url}", response=response)
        except (requests.ConnectionError, requests.Timeout) as exc:
            error = exc
        if attempt == retries:
            raise error
        time.sleep(backoff * 2 ** attempt)
```

1 initial try + 3 retries, sleeps 1s, 2s, 4s. Retries only connection errors, timeouts, 429, 5xx. Other 4xx raise at once.

Use on idempotent requests only: retrying POST can duplicate the write.
